// handoff: ADM-W1-BENCH1

export interface RateLimiterOptions {
  capacity: number;
  refillPerSecond: number;
  /** Clock in milliseconds. Defaults to Date.now. */
  now?: () => number;
}

export interface TakeResult {
  allowed: boolean;
  /** Whole tokens left after the call. */
  remaining: number;
  /** Milliseconds until `cost` tokens are available. 0 when allowed. */
  retryAfterMs: number;
}

interface Bucket {
  tokens: number;
  updatedAt: number;
}

/**
 * Token bucket per key. Keys start full and refill continuously up to capacity.
 */
export function createRateLimiter(options: RateLimiterOptions) {
  const { capacity, refillPerSecond } = options;
  const now = options.now ?? Date.now;
  const buckets = new Map<string, Bucket>();

  function refill(bucket: Bucket, at: number): void {
    const elapsedMs = at - bucket.updatedAt;
    if (elapsedMs > 0) {
      if (refillPerSecond > 0) {
        bucket.tokens = Math.min(capacity, bucket.tokens + (elapsedMs / 1000) * refillPerSecond);
      }
      bucket.updatedAt = at;
    }
  }

  return {
    take(key: string, cost = 1): TakeResult {
      if (!Number.isInteger(cost) || cost < 1 || cost > capacity) {
        throw new RangeError(`cost must be an integer from 1 to ${capacity}, got ${cost}`);
      }

      const at = now();
      let bucket = buckets.get(key);
      if (!bucket) {
        bucket = { tokens: capacity, updatedAt: at };
        buckets.set(key, bucket);
      }
      refill(bucket, at);

      // A small epsilon keeps floating point refill from denying a token that
      // has effectively arrived already.
      if (bucket.tokens + 1e-9 >= cost) {
        bucket.tokens = Math.max(0, bucket.tokens - cost);
        return { allowed: true, remaining: Math.floor(bucket.tokens), retryAfterMs: 0 };
      }

      const missing = cost - bucket.tokens;
      const retryAfterMs =
        refillPerSecond > 0 ? Math.ceil((missing / refillPerSecond) * 1000) : Number.POSITIVE_INFINITY;
      return { allowed: false, remaining: Math.floor(bucket.tokens), retryAfterMs };
    },
  };
}

import { dueDate } from "./dates.ts";
import { sampleInvoices, totalCents } from "./invoices.ts";
import type { Invoice } from "./invoices.ts";
import { paginate } from "./paginate.ts";
import { createRateLimiter } from "./rate-limiter.ts";

export interface Request {
  method: string;
  /** Path with an optional query string, for example `/invoices?limit=20`. */
  path: string;
  /** Header names are lowercase. */
  headers?: Record<string, string>;
}

export interface Response {
  status: number;
  headers: Record<string, string>;
  body: unknown;
}

export interface RateLimitOptions {
  capacity: number;
  refillPerSecond: number;
  now?: () => number;
}

export interface AppOptions {
  invoices?: Invoice[];
  rateLimit?: RateLimitOptions;
}

function json(status: number, body: unknown, headers: Record<string, string> = {}): Response {
  return { status, headers: { "content-type": "application/json", ...headers }, body };
}

function toSummary(invoice: Invoice) {
  return {
    id: invoice.id,
    client: invoice.client,
    status: invoice.status,
    currency: invoice.currency,
    totalCents: totalCents(invoice),
    due: dueDate(invoice),
  };
}

export function createApp(options: AppOptions = {}) {
  const invoices = options.invoices ?? sampleInvoices(57);
  const byId = new Map(invoices.map((invoice) => [invoice.id, invoice]));
  const limiter = options.rateLimit ? createRateLimiter(options.rateLimit) : undefined;

  function dispatch(request: Request, url: URL): Response {
    if (request.method !== "GET") {
      return json(405, { error: "method_not_allowed" });
    }
    if (url.pathname === "/health") {
      return json(200, { ok: true });
    }
    if (url.pathname === "/invoices") {
      const page = Number(url.searchParams.get("page") ?? "1");
      const pageSize = Number(url.searchParams.get("pageSize") ?? "20");
      try {
        const result = paginate(invoices, page, pageSize);
        return json(200, { ...result, items: result.items.map(toSummary) });
      } catch (error) {
        if (error instanceof RangeError) {
          return json(400, { error: "bad_request", message: error.message });
        }
        throw error;
      }
    }

    const match = /^\/invoices\/([\w-]+)$/.exec(url.pathname);
    if (match) {
      const invoice = byId.get(match[1]!);
      return invoice ? json(200, invoice) : json(404, { error: "not_found" });
    }
    return json(404, { error: "not_found" });
  }

  function handle(request: Request): Response {
    const url = new URL(request.path, "http://ledger.local");
    const isHealth = request.method === "GET" && url.pathname === "/health";

    let limitHeaders: Record<string, string> = {};
    if (limiter && !isHealth) {
      const key = request.headers?.["x-api-key"] ?? "anonymous";
      const result = limiter.take(key);
      limitHeaders = { "x-ratelimit-remaining": String(result.remaining) };
      if (!result.allowed) {
        return json(429, { error: "rate_limited" }, {
          ...limitHeaders,
          "retry-after": String(Math.max(1, Math.ceil(result.retryAfterMs / 1000))),
        });
      }
    }

    const response = dispatch(request, url);
    return { ...response, headers: { ...response.headers, ...limitHeaders } };
  }

  return { handle };
}

