test("a new key starts with capacity tokens", () => {
  let time = 0;
  const limiter = createRateLimiter({ capacity: 3, refillPerSecond: 1, now: () => time });
  assert.deepEqual(limiter.take("a"), { allowed: true, remaining: 2, retryAfterMs: 0 });
  assert.deepEqual(limiter.take("a"), { allowed: true, remaining: 1, retryAfterMs: 0 });
  assert.deepEqual(limiter.take("a"), { allowed: true, remaining: 0, retryAfterMs: 0 });
});

test("a denied take removes nothing and reports the wait", () => {
  let time = 0;
  const limiter = createRateLimiter({ capacity: 2, refillPerSecond: 1, now: () => time });
  limiter.take("a", 2);
  const denied = limiter.take("a");
  assert.deepEqual(denied, { allowed: false, remaining: 0, retryAfterMs: 1000 });

  time = 250;
  assert.deepEqual(limiter.take("a"), { allowed: false, remaining: 0, retryAfterMs: 750 });

  time = 1000;
  assert.deepEqual(limiter.take("a"), { allowed: true, remaining: 0, retryAfterMs: 0 });
});

test("tokens refill continuously but never exceed capacity", () => {
  let time = 0;
  const limiter = createRateLimiter({ capacity: 2, refillPerSecond: 0.5, now: () => time });
  limiter.take("a", 2);

  time = 1000;
  assert.deepEqual(limiter.take("a"), { allowed: false, remaining: 0, retryAfterMs: 1000 });

