// handoff: ADM-W2-BENCH2

import type { Invoice } from "./invoices.ts";

const DAY_MS = 86_400_000;
const DAY_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * Parses a calendar date in YYYY-MM-DD form.
 *
 * Dates are anchored at UTC midnight and all day arithmetic stays in UTC, so
 * parsing, formatting and offsets do not depend on the machine's time zone.
 */
export function parseDay(day: string): Date {
  const match = DAY_PATTERN.exec(day);
  if (!match) {
    throw new RangeError(`invalid day: ${day}`);
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const dayOfMonth = Number(match[3]);

  const date = new Date(0);
  date.setUTCHours(0, 0, 0, 0);
  // setUTCFullYear (unlike the constructor) keeps years 0-99 literal.
  date.setUTCFullYear(year, month - 1, dayOfMonth);

  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== dayOfMonth
  ) {
    throw new RangeError(`invalid day: ${day}`);
  }
  return date;
}

/** Formats a date as YYYY-MM-DD in UTC. */
export function formatDay(date: Date): string {
  const year = String(date.getUTCFullYear()).padStart(4, "0");
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function addDays(day: string, days: number): string {
  return formatDay(new Date(parseDay(day).getTime() + days * DAY_MS));
}

export function dueDate(invoice: Pick<Invoice, "issued" | "netDays">): string {
  return addDays(invoice.issued, invoice.netDays);
}

/** Whole days past the due date. 0 when the invoice is not overdue. */
export function daysOverdue(invoice: Pick<Invoice, "issued" | "netDays">, today: string): number {
  const difference = parseDay(today).getTime() - parseDay(dueDate(invoice)).getTime();
  return Math.max(0, Math.round(difference / DAY_MS));
}

export function isOverdue(invoice: Pick<Invoice, "issued" | "netDays">, today: string): boolean {
  return daysOverdue(invoice, today) > 0;
}

import test from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { addDays, daysOverdue, dueDate, formatDay, isOverdue, parseDay } from "../src/dates.ts";

const TIME_ZONES = ["America/Los_Angeles", "UTC", "Asia/Tokyo"];
const datesUrl = new URL("../src/dates.ts", import.meta.url).href;

// Runs in a child process so each zone really is a fresh process-wide TZ.
const childChecks = `
import assert from "node:assert/strict";
import { addDays, daysOverdue, dueDate, formatDay, isOverdue, parseDay } from ${JSON.stringify(datesUrl)};

for (const day of ["2026-01-01", "2026-03-01", "2026-03-08", "2026-06-15", "2026-11-01", "2026-12-31"]) {
  assert.equal(formatDay(parseDay(day)), day, "round trip " + day);
}

assert.equal(addDays("2026-03-01", 30), "2026-03-31");
assert.equal(addDays("2026-03-07", 1), "2026-03-08");
assert.equal(addDays("2026-03-08", 1), "2026-03-09");
assert.equal(addDays("2026-11-01", 1), "2026-11-02");
assert.equal(addDays("2026-12-31", 1), "2027-01-01");

const invoice = { issued: "2026-03-01", netDays: 30 };
assert.equal(dueDate(invoice), "2026-03-31");
assert.equal(daysOverdue(invoice, "2026-03-30"), 0);
assert.equal(daysOverdue(invoice, "2026-03-31"), 0);
assert.equal(daysOverdue(invoice, "2026-04-01"), 1);
assert.equal(daysOverdue(invoice, "2026-04-10"), 10);
assert.equal(isOverdue(invoice, "2026-03-31"), false);
assert.equal(isOverdue(invoice, "2026-04-01"), true);

console.log("zone-ok");
`;

for (const zone of TIME_ZONES) {
  test(`dates are identical under TZ=${zone}`, () => {
    const output = execFileSync(process.execPath, ["--input-type=module", "-e", childChecks], {
      env: { ...process.env, TZ: zone },
      encoding: "utf8",
    });
    assert.match(output, /zone-ok/);
  });
}

test("parseDay rejects impossible calendar days instead of rolling over", () => {
  assert.throws(() => parseDay("2026-02-29"), RangeError);
  assert.throws(() => parseDay("2026-02-30"), RangeError);
  assert.throws(() => parseDay("2026-13-01"), RangeError);
  assert.throws(() => parseDay("2026-1-01"), RangeError);
