// handoff: ADM-W3-BENCH3

export interface Page<T> {
  items: T[];
  /** 1-based page number. */
  page: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
  hasPrevious: boolean;
  hasNext: boolean;
}

export function paginate<T>(all: readonly T[], page: number, pageSize: number): Page<T> {
  if (!Number.isInteger(page) || page < 1) {
    throw new RangeError(`page must be an integer >= 1, got ${page}`);
  }
  if (!Number.isInteger(pageSize) || pageSize < 1) {
    throw new RangeError(`pageSize must be an integer >= 1, got ${pageSize}`);
  }

  const totalItems = all.length;
  const totalPages = Math.ceil(totalItems / pageSize);
  const start = (page - 1) * pageSize;
  // slice() excludes the end index, so the page boundary is exactly start + pageSize.
  const end = start + pageSize;

  return {
    items: all.slice(start, end),
    page,
    pageSize,
    totalItems,
    totalPages,
    hasPrevious: page > 1,
    hasNext: page < totalPages,
  };
}

/**
 * Cursors are opaque to clients: a base64url encoded marker holding the id of
 * the last item already delivered. New invoices always get a higher id, so
 * walking the cursor never repeats or skips an invoice that already existed.
 */
interface CursorPayload {
  v: 1;
  id: string;
}

export function encodeCursor(id: string): string {
  return Buffer.from(JSON.stringify({ v: 1, id } satisfies CursorPayload), "utf8").toString("base64url");
}

/** Returns the id encoded in a cursor. Throws RangeError for malformed input. */
export function decodeCursor(cursor: string): string {
  if (!/^[A-Za-z0-9_-]+$/.test(cursor)) {
    throw new RangeError("invalid cursor");
  }

  let payload: unknown;
  try {
    payload = JSON.parse(Buffer.from(cursor, "base64url").toString("utf8"));
  } catch {
    throw new RangeError("invalid cursor");
  }

  if (typeof payload !== "object" || payload === null || Array.isArray(payload)) {
    throw new RangeError("invalid cursor");
  }
  const record = payload as Record<string, unknown>;
  if (record.v !== 1 || typeof record.id !== "string") {
    throw new RangeError("invalid cursor");
  }
  return record.id;
}

