import test from "node:test";
import assert from "node:assert/strict";
import { createApp } from "../src/api.ts";
import { paginate } from "../src/paginate.ts";
import type { Invoice } from "../src/invoices.ts";
import type { Response } from "../src/api.ts";

function makeInvoice(id: string): Invoice {
  return {
    id,
    client: "Globex",
    issued: "2026-01-01",
    netDays: 30,
    status: "sent",
    currency: "USD",
    items: [{ description: "Audit", quantity: 1, unitPriceCents: 1000, taxRate: 0 }],
  };
}

interface ListBody {
  items: { id: string }[];
  nextCursor: string | null;
  limit: number;
}

function list(app: ReturnType<typeof createApp>, path: string): Response {
  return app.handle({ method: "GET", path });
}

function bodyOf(response: Response): ListBody {
  assert.equal(response.status, 200);
  return response.body as ListBody;
}

function walk(app: ReturnType<typeof createApp>, limit: number): { ids: string[]; pages: number } {
  const ids: string[] = [];
  let cursor: string | null = null;
  for (let pages = 0; pages < 1000; pages++) {
    const path =
      cursor === null
        ? `/invoices?limit=${limit}`
        : `/invoices?limit=${limit}&cursor=${encodeURIComponent(cursor)}`;
    const body = bodyOf(list(app, path));
    assert.equal(body.limit, limit);
    ids.push(...body.items.map((item) => item.id));
    if (body.nextCursor === null) {
      return { ids, pages: pages + 1 };
    }
    cursor = body.nextCursor;
  }
  throw new Error("cursor walk did not terminate");
}

test("paginate returns at most pageSize items and stops on the last page", () => {
  const all = [1, 2, 3, 4, 5];
  const first = paginate(all, 1, 2);
  assert.deepEqual(first.items, [1, 2]);
  assert.equal(first.hasNext, true);

  const second = paginate(all, 2, 2);
  assert.deepEqual(second.items, [3, 4]);
  assert.equal(second.hasNext, true);

  const third = paginate(all, 3, 2);
  assert.deepEqual(third.items, [5]);
  assert.equal(third.hasNext, false);
  assert.equal(third.hasPrevious, true);

  for (const page of [1, 2, 3]) {
    assert.ok(paginate(all, page, 2).items.length <= 2);
  }
});

test("GET /invoices defaults to limit 20 and returns cursor page fields", () => {
  const invoices = Array.from({ length: 25 }, (_, index) =>
    makeInvoice(`INV-${String(1001 + index).padStart(5, "0")}`),
  );
  const app = createApp({ invoices });
  const response = list(app, "/invoices");
  const body = bodyOf(response);

  assert.equal(body.limit, 20);
  assert.equal(body.items.length, 20);
  assert.equal(typeof body.nextCursor, "string");
  assert.equal("page" in body, false);
  assert.equal("pageSize" in body, false);
  assert.equal("totalItems" in body, false);
});

test("cursor pagination walks every invoice exactly once in id order", () => {
  const invoices = [makeInvoice("INV-01005"), makeInvoice("INV-01001"), makeInvoice("INV-01003")];
  const app = createApp({ invoices });
  const { ids } = walk(app, 1);
  assert.deepEqual(ids, ["INV-01001", "INV-01003", "INV-01005"]);
});

test("the last page has a null nextCursor", () => {
  const app = createApp({ invoices: [makeInvoice("INV-01001"), makeInvoice("INV-01002")] });
  const body = bodyOf(list(app, "/invoices?limit=2"));
  assert.equal(body.items.length, 2);
  assert.equal(body.nextCursor, null);
});

test("invoices added between requests do not disturb the original walk", () => {
  const invoices = Array.from({ length: 7 }, (_, index) =>
    makeInvoice(`INV-${String(1001 + index).padStart(5, "0")}`),
  );
  const original = invoices.map((invoice) => invoice.id);
  const app = createApp({ invoices });

  const first = bodyOf(list(app, "/invoices?limit=2"));
  assert.equal(first.items.length, 2);

  invoices.push(makeInvoice("INV-01008"), makeInvoice("INV-01009"));

  const seen = new Set(first.items.map((item) => item.id));
  let cursor = first.nextCursor;
  while (cursor !== null) {
    const page = bodyOf(list(app, `/invoices?limit=2&cursor=${encodeURIComponent(cursor)}`));
    for (const item of page.items) {
      assert.equal(seen.has(item.id), false, `${item.id} appeared twice`);
      seen.add(item.id);
    }
    cursor = page.nextCursor;
  }

  for (const id of original) {
    assert.equal(seen.has(id), true, `${id} was skipped`);
  }
});

test("limit must be an integer from 1 to 100", () => {
  const app = createApp({ invoices: [] });
  for (const limit of ["0", "101", "1.5", "-1", "abc", "", "1e2"]) {
    const response = list(app, `/invoices?limit=${encodeURIComponent(limit)}`);
