  for (const path of ["/invoices?page=2", "/invoices?pageSize=10", "/invoices?page=1&pageSize=5"]) {
    const response = list(app, path);
    assert.equal(response.status, 400);
    assert.deepEqual(response.body, { error: "use_cursor" });
