function parseInvoiceBody(body: unknown): NewInvoice | string {
  if (!isRecord(body)) return "body must be a JSON object";

  const client = body.client;
  if (typeof client !== "string" || client.trim() === "") return "client must be a non-empty string";

  const issued = body.issued;
  if (typeof issued !== "string") return "issued must be a YYYY-MM-DD date";
