  const netDays = body.netDays;
  if (!isInteger(netDays) || netDays < 0) return "netDays must be an integer >= 0";

  const currency = body.currency;
  if (typeof currency !== "string" || !(CURRENCIES as readonly string[]).includes(currency)) {
    return 'currency must be "USD", "EUR" or "MXN"';
  }

  const status = body.status ?? "draft";
  if (typeof status !== "string" || !(STATUSES as readonly string[]).includes(status)) {
    return 'status must be "draft", "sent", "paid" or "void"';
  }

  const rawItems = body.items;
  if (!Array.isArray(rawItems) || rawItems.length === 0) return "items must be a non-empty array";

  const items: LineItem[] = [];
  for (let index = 0; index < rawItems.length; index++) {
    const raw = rawItems[index];
    if (!isRecord(raw)) return `items[${index}] must be an object`;
    const description = raw.description ?? "";
    if (typeof description !== "string") return `items[${index}].description must be a string`;
    const quantity = raw.quantity;
    if (!isInteger(quantity) || quantity < 1) return `items[${index}].quantity must be an integer >= 1`;
    const unitPriceCents = raw.unitPriceCents;
    if (!isInteger(unitPriceCents) || unitPriceCents < 0) return `items[${index}].unitPriceCents must be an integer >= 0`;
    const taxRate = raw.taxRate;
    if (typeof taxRate !== "number" || !Number.isFinite(taxRate) || taxRate < 0 || taxRate > 1) {
      return `items[${index}].taxRate must be a number from 0 to 1`;
    }
    items.push({ description, quantity, unitPriceCents, taxRate });
  }

  return {
    client,
    issued,
    netDays,
    status: status as Status,
    currency: currency as Currency,
    items,
  };
}
