// handoff: ADM-W4-BENCH4

export interface StoredResponse {
  status: number;
  headers: Record<string, string>;
  body: unknown;
}

export type LookupResult =
  | { kind: "miss" }
  | { kind: "replay"; response: StoredResponse }
  | { kind: "conflict" };

interface Entry {
  bodyKey: string;
  response: StoredResponse;
  storedAt: number;
}

const DEFAULT_TTL_MS = 24 * 60 * 60 * 1000;

function canonicalize(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(canonicalize);
  }
  if (value !== null && typeof value === "object") {
    const source = value as Record<string, unknown>;
    // Null prototype keeps a "__proto__" key an ordinary own property.
    const sorted: Record<string, unknown> = Object.create(null);
    for (const key of Object.keys(source).sort()) {
      sorted[key] = canonicalize(source[key]);
    }
    return sorted;
  }
  return value;
}

/** JSON text with object keys sorted, so key order does not affect equality. */
export function canonicalJson(value: unknown): string {
  const text = JSON.stringify(canonicalize(value));
  return text === undefined ? "undefined" : text;
}

/**
 * Remembers the first successful response per idempotency key for 24 hours.
 * Results are compared by JSON value, not by key order.
 */
export function createIdempotencyStore(ttlMs = DEFAULT_TTL_MS) {
  const entries = new Map<string, Entry>();

  return {
    lookup(key: string, body: unknown, now: number): LookupResult {
      const entry = entries.get(key);
      if (entry === undefined) {
        return { kind: "miss" };
      }
      if (now - entry.storedAt >= ttlMs) {
        entries.delete(key);
        return { kind: "miss" };
      }
      return entry.bodyKey === canonicalJson(body)
        ? { kind: "replay", response: entry.response }
        : { kind: "conflict" };
    },

    save(key: string, body: unknown, response: StoredResponse, now: number): void {
      entries.set(key, { bodyKey: canonicalJson(body), response, storedAt: now });
    },
  };
}

import { dueDate, parseDay } from "./dates.ts";
import { createIdempotencyStore } from "./idempotency.ts";
import { sampleInvoices, totalCents } from "./invoices.ts";
import type { Currency, Invoice, LineItem, Status } from "./invoices.ts";
import { decodeCursor, encodeCursor } from "./paginate.ts";
import { createRateLimiter } from "./rate-limiter.ts";

export interface Request {
  method: string;
  /** Path with an optional query string, for example `/invoices?limit=20`. */
  path: string;
  /** Header names are lowercase. */
  headers?: Record<string, string>;
  /** Parsed JSON request body, when there is one. */
  body?: unknown;
}

export interface Response {
  status: number;
  headers: Record<string, string>;
  body: unknown;
}

export interface RateLimitOptions {
  capacity: number;
  refillPerSecond: number;
  now?: () => number;
}

export interface AppOptions {
  invoices?: Invoice[];
  rateLimit?: RateLimitOptions;
  /** Clock in milliseconds. Defaults to Date.now. */
  now?: () => number;
}

const STATUSES: readonly Status[] = ["draft", "sent", "paid", "void"];
const CURRENCIES: readonly Currency[] = ["USD", "EUR", "MXN"];

function json(status: number, body: unknown, headers: Record<string, string> = {}): Response {
  return { status, headers: { "content-type": "application/json", ...headers }, body };
}

function toSummary(invoice: Invoice) {
  return {
    id: invoice.id,
    client: invoice.client,
    status: invoice.status,
    currency: invoice.currency,
    totalCents: totalCents(invoice),
    due: dueDate(invoice),
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value);
}

interface NewInvoice {
  client: string;
  issued: string;
  netDays: number;
  status: Status;
  currency: Currency;
  items: LineItem[];
}

/** Returns the clean invoice fields, or a message describing the first problem. */
function parseInvoiceBody(body: unknown): NewInvoice | string {
  if (!isRecord(body)) {
    return "body must be a JSON object";
  }

  if (typeof body.client !== "string" || body.client.trim() === "") {
    return "client must be a non-empty string";
  }

  if (typeof body.issued !== "string") {
    return "issued must be a YYYY-MM-DD date";
  }
  try {
    parseDay(body.issued);
  } catch {
    return "issued must be a valid YYYY-MM-DD date";
  }

  if (!isInteger(body.netDays) || body.netDays < 0) {
    return "netDays must be an integer >= 0";
  }

  if (typeof body.currency !== "string" || !CURRENCIES.includes(body.currency as Currency)) {
    return 'currency must be "USD", "EUR" or "MXN"';
  }

  const status = body.status === undefined ? "draft" : body.status;
  if (typeof status !== "string" || !STATUSES.includes(status as Status)) {
    return 'status must be "draft", "sent", "paid" or "void"';
  }

  if (!Array.isArray(body.items) || body.items.length === 0) {
    return "items must be a non-empty array";
  }

  const items: LineItem[] = [];
  for (let index = 0; index < body.items.length; index += 1) {
    const raw = body.items[index];
    if (!isRecord(raw)) {
      return `items[${index}] must be an object`;
    }

    const description = raw.description === undefined ? "" : raw.description;
    if (typeof description !== "string") {
      return `items[${index}].description must be a string`;
    }
    if (!isInteger(raw.quantity) || raw.quantity < 1) {
      return `items[${index}].quantity must be an integer >= 1`;
    }
    if (!isInteger(raw.unitPriceCents) || raw.unitPriceCents < 0) {
      return `items[${index}].unitPriceCents must be an integer >= 0`;
    }
    if (
      typeof raw.taxRate !== "number" ||
      !Number.isFinite(raw.taxRate) ||
      raw.taxRate < 0 ||
      raw.taxRate > 1
    ) {
      return `items[${index}].taxRate must be a number from 0 to 1`;
    }

    items.push({
      description,
      quantity: raw.quantity,
      unitPriceCents: raw.unitPriceCents,
      taxRate: raw.taxRate,
    });
  }

  return {
    client: body.client,
    issued: body.issued,
    netDays: body.netDays,
    status: status as Status,
    currency: body.currency as Currency,
    items,
  };
}

export function createApp(options: AppOptions = {}) {
  const invoices = options.invoices ?? sampleInvoices(57);
  const byId = new Map(invoices.map((invoice) => [invoice.id, invoice]));
  const limiter = options.rateLimit ? createRateLimiter(options.rateLimit) : undefined;
  const now = options.now ?? Date.now;
  const idempotency = createIdempotencyStore();

  function nextInvoiceId(): string {
    let highest = 0;
    for (const invoice of invoices) {
      const match = /^INV-(\d+)$/.exec(invoice.id);
      if (match) {
        highest = Math.max(highest, Number(match[1]));
      }
    }
    return `INV-${String(highest + 1).padStart(5, "0")}`;
  }

  function createInvoice(request: Request): Response {
    const parsed = parseInvoiceBody(request.body);
    if (typeof parsed === "string") {
      return json(400, { error: "invalid_invoice", message: parsed });
    }

    const key = request.headers?.["idempotency-key"];
    const at = now();

    if (key !== undefined) {
      const found = idempotency.lookup(key, request.body, at);
      if (found.kind === "conflict") {
        return json(422, { error: "idempotency_key_reused" });
      }
      if (found.kind === "replay") {
        return {
          status: found.response.status,
          headers: { ...found.response.headers, "idempotent-replay": "true" },
          body: structuredClone(found.response.body),
        };
      }
    }

    const invoice: Invoice = { id: nextInvoiceId(), ...parsed };
    invoices.push(invoice);
    byId.set(invoice.id, invoice);

    const response = json(201, invoice, { location: `/invoices/${invoice.id}` });
    if (key !== undefined) {
      idempotency.save(key, request.body, response, at);
    }
    return response;
  }

  function listInvoices(url: URL): Response {
    if (url.searchParams.has("page") || url.searchParams.has("pageSize")) {
      return json(400, { error: "use_cursor" });
    }

    let limit = 20;
    const limitParam = url.searchParams.get("limit");
    if (limitParam !== null) {
      if (!/^\d+$/.test(limitParam)) {
        return json(400, { error: "bad_request" });
      }
      limit = Number(limitParam);
      if (!Number.isSafeInteger(limit) || limit < 1 || limit > 100) {
        return json(400, { error: "bad_request" });
      }
    }

    let afterId: string | null = null;
    const cursorParam = url.searchParams.get("cursor");
    if (cursorParam !== null) {
      try {
        afterId = decodeCursor(cursorParam);
      } catch {
        return json(400, { error: "bad_cursor" });
      }
    }

    const sorted = [...invoices].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
    const candidates = afterId === null ? sorted : sorted.filter((invoice) => invoice.id > afterId);
    const pageItems = candidates.slice(0, limit);
    const nextCursor =
      candidates.length > limit ? encodeCursor(pageItems[pageItems.length - 1]!.id) : null;

    return json(200, { items: pageItems.map(toSummary), nextCursor, limit });
  }

  function dispatch(request: Request, url: URL): Response {
    if (request.method !== "GET" && request.method !== "POST") {
      return json(405, { error: "method_not_allowed" });
    }
    if (url.pathname === "/health") {
      return request.method === "GET"
        ? json(200, { ok: true })
        : json(405, { error: "method_not_allowed" });
    }
    if (url.pathname === "/invoices") {
      return request.method === "POST" ? createInvoice(request) : listInvoices(url);
    }
    if (request.method === "GET") {
      const match = /^\/invoices\/([\w-]+)$/.exec(url.pathname);
      if (match) {
        const invoice = byId.get(match[1]!);
        return invoice ? json(200, invoice) : json(404, { error: "not_found" });
      }
    }
    return json(404, { error: "not_found" });
  }

  function handle(request: Request): Response {
    const url = new URL(request.path, "http://ledger.local");
    const isHealth = request.method === "GET" && url.pathname === "/health";

    let limitHeaders: Record<string, string> = {};
    if (limiter && !isHealth) {
      const key = request.headers?.["x-api-key"] ?? "anonymous";
      const result = limiter.take(key);
      limitHeaders = { "x-ratelimit-remaining": String(result.remaining) };
      if (!result.allowed) {
        return json(429, { error: "rate_limited" }, {
          ...limitHeaders,
          "retry-after": String(Math.max(1, Math.ceil(result.retryAfterMs / 1000))),
        });
      }
    }

    const response = dispatch(request, url);
    return { ...response, headers: { ...response.headers, ...limitHeaders } };
  }

  return { handle };
}

import { createServer } from "node:http";
import { createApp } from "./api.ts";

const app = createApp({ rateLimit: { capacity: 60, refillPerSecond: 1 } });
const port = Number(process.env.PORT ?? 3000);

createServer((incoming, outgoing) => {
  void (async () => {
    const headers: Record<string, string> = {};
    for (const [name, value] of Object.entries(incoming.headers)) {
      if (typeof value === "string") headers[name.toLowerCase()] = value;
    }

    const chunks: Buffer[] = [];
    for await (const chunk of incoming) {
      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    }
    const text = Buffer.concat(chunks).toString("utf8");
    let body: unknown;
    if (text.trim() !== "") {
      try {
        body = JSON.parse(text);
      } catch {
        body = undefined;
      }
    }

    const response = app.handle({
      method: incoming.method ?? "GET",
      path: incoming.url ?? "/",
      headers,
      body,
    });
    outgoing.writeHead(response.status, response.headers);
    outgoing.end(JSON.stringify(response.body));
  })().catch(() => {
    if (!outgoing.headersSent) {
      outgoing.writeHead(500, { "content-type": "application/json" });
    }
    outgoing.end(JSON.stringify({ error: "internal_error" }));
  });
}).listen(port, () => {
  console.log(`ledger listening on http://localhost:${port}`);
});

