test("an idempotency key replays the first response without creating again", () => {
  const app = createApp({ invoices: [] });
  const body = validBody();

  const first = post(app, body, { "idempotency-key": "key-1" });
  assert.equal(first.status, 201);
  assert.equal(first.headers["idempotent-replay"], undefined);

  // Same JSON value, different key order at both levels.
  const reordered = {
    items: [{ taxRate: 0.1, unitPriceCents: 100, quantity: 1, description: "Work" }],
    currency: "USD",
    netDays: 30,
    issued: "2026-03-01",
    client: "Acme",
  };
  const second = post(app, reordered, { "idempotency-key": "key-1" });

  assert.equal(second.status, 201);
  assert.equal(second.headers["idempotent-replay"], "true");
  assert.equal(second.headers["location"], first.headers["location"]);
  assert.deepEqual(second.body, first.body);
  assert.equal(listIds(app).length, 1);
});

test("the same key with a different body returns 422", () => {
  const app = createApp({ invoices: [] });
  const first = post(app, validBody(), { "idempotency-key": "key-1" });
  assert.equal(first.status, 201);

  const conflict = post(app, validBody({ client: "Someone Else" }), { "idempotency-key": "key-1" });
  assert.equal(conflict.status, 422);
  assert.deepEqual(conflict.body, { error: "idempotency_key_reused" });
  assert.equal(listIds(app).length, 1);
});

test("a 400 is not stored, so the key can be retried with a fixed body", () => {
  const app = createApp({ invoices: [] });
  const invalid = post(app, validBody({ client: "" }), { "idempotency-key": "key-1" });
  assert.equal(invalid.status, 400);

  const fixed = post(app, validBody(), { "idempotency-key": "key-1" });
  assert.equal(fixed.status, 201);
  assert.equal(fixed.headers["idempotent-replay"], undefined);
  assert.equal(listIds(app).length, 1);
});

test("a key expires 24 hours after its first use", () => {
  const ttl = 24 * 60 * 60 * 1000;
  let time = 0;
  const app = createApp({ invoices: [], now: () => time });
  const body = validBody();

  const first = post(app, body, { "idempotency-key": "key-1" });
  assert.equal(first.status, 201);
  const firstId = (first.body as Invoice).id;

  time = ttl - 1;
  const replay = post(app, body, { "idempotency-key": "key-1" });
  assert.equal(replay.status, 201);
  assert.equal(replay.headers["idempotent-replay"], "true");
  assert.equal((replay.body as Invoice).id, firstId);

  time = ttl;
  const afterExpiry = post(app, body, { "idempotency-key": "key-1" });
  assert.equal(afterExpiry.status, 201);
  assert.equal(afterExpiry.headers["idempotent-replay"], undefined);
  assert.notEqual((afterExpiry.body as Invoice).id, firstId);
});

test("an expired key with a different body acts as a new key", () => {
  const ttl = 24 * 60 * 60 * 1000;
  let time = 0;
  const app = createApp({ invoices: [], now: () => time });
  post(app, validBody(), { "idempotency-key": "key-1" });

  time = ttl;
  const response = post(app, validBody({ client: "Other" }), { "idempotency-key": "key-1" });
  assert.equal(response.status, 201);
  assert.equal(response.headers["idempotent-replay"], undefined);
});

test("requests without a key always create a new invoice", () => {
  const app = createApp({ invoices: [] });
  const first = post(app, validBody());
  const second = post(app, validBody());
  assert.equal(first.status, 201);
  assert.equal(second.status, 201);
  assert.notEqual((first.body as Invoice).id, (second.body as Invoice).id);
  assert.equal(listIds(app).length, 2);
});

test("POST is allowed but other methods still return 405", () => {
  const app = createApp({ invoices: [] });
  assert.equal(app.handle({ method: "DELETE", path: "/invoices" }).status, 405);
  assert.equal(app.handle({ method: "PATCH", path: "/invoices" }).status, 405);
  assert.equal(app.handle({ method: "PUT", path: "/invoices/INV-01001" }).status, 405);
});

