/**
 * Cursors are opaque to clients: a base64url encoded marker holding the id of
 * the last item already delivered plus the highest id present when the walk
 * started. New invoices get higher ids, so the snapshot bound keeps them out
 * of a walk that began before they existed.
 */
interface CursorPayload {
  v: 1;
  id: string;
  upTo: string;
}

export function encodeCursor(id: string, upTo: string = id): string {
  return Buffer.from(
    JSON.stringify({ v: 1, id, upTo } satisfies CursorPayload),
    "utf8",
  ).toString("base64url");
}

/** Decodes a cursor. Throws RangeError for malformed input. */
export function decodeCursor(cursor: string): { afterId: string; upTo: string } {
  if (!/^[A-Za-z0-9_-]+$/.test(cursor)) {
    throw new RangeError("invalid cursor");
  }

  let payload: unknown;
  try {
    payload = JSON.parse(Buffer.from(cursor, "base64url").toString("utf8"));
  } catch {
    throw new RangeError("invalid cursor");
  }

  if (typeof payload !== "object" || payload === null || Array.isArray(payload)) {
    throw new RangeError("invalid cursor");
  }
  const record = payload as Record<string, unknown>;
  if (record.v !== 1 || typeof record.id !== "string" || typeof record.upTo !== "string") {
    throw new RangeError("invalid cursor");
  }
  return { afterId: record.id, upTo: record.upTo };
}

