import test from "node:test";
import assert from "node:assert/strict";
import { createApp } from "../src/api.ts";

const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

test("every response gets an x-request-id, generated as a UUID when absent", () => {
  const app = createApp({ invoices: [] });
  for (const request of [
    { method: "GET", path: "/health" },
    { method: "GET", path: "/invoices" },
    { method: "GET", path: "/missing" },
    { method: "DELETE", path: "/invoices" },
  ]) {
    const response = app.handle(request);
    assert.match(response.headers["x-request-id"] ?? "", UUID_V4, `${request.method} ${request.path}`);
  }
});

test("generated request ids differ between requests", () => {
  const app = createApp({ invoices: [] });
  const ids = new Set<string>();
  for (let index = 0; index < 20; index += 1) {
    const response = app.handle({ method: "GET", path: "/health" });
    ids.add(response.headers["x-request-id"]!);
  }
  assert.equal(ids.size, 20);
});

test("an incoming x-request-id is echoed unchanged", () => {
  const app = createApp({ invoices: [] });
  for (const path of ["/health", "/invoices", "/missing"]) {
    const response = app.handle({
      method: "GET",
      path,
      headers: { "x-request-id": "client-request-42" },
    });
    assert.equal(response.headers["x-request-id"], "client-request-42");
  }
});

test("rate limited responses also carry x-request-id", () => {
  const app = createApp({ invoices: [], rateLimit: { capacity: 1, refillPerSecond: 0 } });

  const allowed = app.handle({
    method: "GET",
    path: "/invoices",
    headers: { "x-request-id": "allowed-id" },
  });
  assert.equal(allowed.headers["x-request-id"], "allowed-id");

  const limited = app.handle({
    method: "GET",
    path: "/invoices",
    headers: { "x-request-id": "limited-id" },
  });
  assert.equal(limited.status, 429);
  assert.equal(limited.headers["x-request-id"], "limited-id");
});

