import test from "node:test";
import assert from "node:assert/strict";
import { createApp } from "../src/api.ts";
import type { Invoice } from "../src/invoices.ts";

const invoice: Invoice = {
  id: "INV-05001",
  client: "Globex",
  issued: "2026-03-01",
  netDays: 30,
  status: "sent",
  currency: "USD",
  items: [
    { description: "Design sprint", quantity: 2, unitPriceCents: 450_000, taxRate: 0.21 },
    { description: "Support hours", quantity: 3, unitPriceCents: 9_500, taxRate: 0 },
    { description: "Free sample", quantity: 1, unitPriceCents: 0, taxRate: 0 },
  ],
};

test("GET /invoices/:id/lines returns quantity, unitCents and lineTotalCents", () => {
  const app = createApp({ invoices: [invoice] });
  const response = app.handle({ method: "GET", path: "/invoices/INV-05001/lines" });

  assert.equal(response.status, 200);
  assert.deepEqual(response.body, {
    lines: [
      { quantity: 2, unitCents: 450_000, lineTotalCents: 900_000 },
      { quantity: 3, unitCents: 9_500, lineTotalCents: 28_500 },
      { quantity: 1, unitCents: 0, lineTotalCents: 0 },
    ],
  });
});

test("GET /invoices/:id/lines returns 404 for an unknown id", () => {
  const app = createApp({ invoices: [invoice] });
  const response = app.handle({ method: "GET", path: "/invoices/INV-09999/lines" });

  assert.equal(response.status, 404);
  assert.deepEqual(response.body, { error: "not_found" });
});

test("GET /invoices/:id/lines returns an empty array for an invoice without items", () => {
  const app = createApp({ invoices: [{ ...invoice, items: [] }] });
  const response = app.handle({ method: "GET", path: "/invoices/INV-05001/lines" });

  assert.equal(response.status, 200);
  assert.deepEqual(response.body, { lines: [] });
});

test("GET /invoices/:id/lines does not change the invoice detail response", () => {
  const app = createApp({ invoices: [invoice] });
  const detail = app.handle({ method: "GET", path: "/invoices/INV-05001" });

  assert.equal(detail.status, 200);
  assert.deepEqual(detail.body, invoice);
});

